c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg


def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M, a=0.0):
    # prograde ISCO radius in meters (Bardeen et al. 1972)
    Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
    Z2 = math.sqrt(3*a**2 + Z1**2)
    if a >= 0:
        r_isco = M * (3 + Z2 - math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    else:
        r_isco = M * (3 + Z2 + math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
    return r_isco * G / c**2  # convert to meters

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def random_spin():
    return random.uniform(-0.99, 0.99)

def run(N=10000):
    results = []
    for _ in range(N):
        M = random.uniform(0.5, 50) * M_sun          # random mass between 0.5 and 50 solar masses
        r_s = schwarzschild_radius(M)
        a = random_spin()
        r_isco = isco_radius(M, a)
        T = hawking_temperature(M)
        l_P = planck_length()
        # dimensionless ratios
        ratio_r = r_isco / r_s
        ratio_T = T / hawking_temperature(M)  # should be 1, but using exact expression for completeness
        results.append({
            "M_solar_masses": M / M_sun,
            "r_s_meters": r_s,
            "r_isco_meters": r_isco,
            "ratio_r": ratio_r,
            "hawking_temperature_K": T,
            "planck_length_meters": l_P,
            "ratio_T": ratio_T
        })
    return results

if __name__ == "__main__":
    data = run(N=10000)
    print(json.dumps(data, indent=2))

